import type { EffortLevel } from "./effort"

import { state } from "./state"

// Explicit overrides, for models whose IDs do not follow the version
// convention below. The derived rule handles every ordinary model, so this
// map only needs an entry when a model breaks the pattern.
const MODEL_ID_MAP: Record<string, string> = {
  "claude-opus-4-7": "claude-opus-4.7",
  "claude-opus-4-6": "claude-opus-4.6",
  "claude-opus-4-5": "claude-opus-4.5",
  "claude-sonnet-4-6": "claude-sonnet-4.6",
  "claude-sonnet-4-5": "claude-sonnet-4.5",
  "claude-sonnet-4": "claude-sonnet-4",
  "claude-opus-4": "claude-opus-4",
  "claude-haiku-4-5": "claude-haiku-4.5",
}

/**
 * Anthropic writes a minor version as `-N`, Copilot writes it as `.N`. That is
 * a format convention between the two APIs rather than a model capability, so
 * it is derived rather than enumerated — an enumerated list silently drops
 * every model released after it was last edited.
 *
 * The minor version is bounded to two digits so an unstripped date suffix
 * (`claude-sonnet-4-20250514`) can never be read as one.
 */
const ANTHROPIC_VERSION = /^(claude-[a-z]+-\d+)-(\d{1,2})$/
const COPILOT_VERSION = /^(claude-[a-z]+-\d+)\.(\d{1,2})$/

/** Legacy effort suffixes that may appear in model names from old configs */
const EFFORT_SUFFIXES: ReadonlyArray<`-${EffortLevel}`> = [
  "-xhigh",
  "-high",
  "-max",
  "-medium",
  "-low",
]

// Reverse map: Copilot dot format → Anthropic dash format
const REVERSE_MODEL_ID_MAP: Record<string, string> = Object.fromEntries(
  Object.entries(MODEL_ID_MAP).map(([k, v]) => [v, k]),
)

/**
 * Strip a legacy effort suffix from a model name.
 * Returns the base name and the effort value (without the dash prefix).
 */
export function extractEffortFromModelName(model: string): {
  base: string
  effort: EffortLevel | undefined
} {
  for (const suffix of EFFORT_SUFFIXES) {
    if (model.endsWith(suffix)) {
      return {
        base: model.slice(0, -suffix.length),
        effort: suffix.slice(1) as EffortLevel, // strip leading dash
      }
    }
  }
  return { base: model, effort: undefined }
}

/**
 * Convert an Anthropic-style model ID to a Copilot-style model ID.
 * Strips date suffixes, effort suffixes, converts dashes to dots,
 * and appends -1m if needed.
 */
export function anthropicToCopilotModelId(
  model: string,
  is1M: boolean,
): string {
  let base = model

  // Strip [1m] suffix if present (Claude Code sends this)
  const has1MBracket = base.endsWith("[1m]")
  if (has1MBracket) {
    base = base.slice(0, -4)
  }

  // Strip -1m suffix if present (legacy config format)
  const has1MDash = !has1MBracket && base.endsWith("-1m")
  if (has1MDash) {
    base = base.slice(0, -3)
  }

  // Strip legacy effort suffixes (e.g. claude-opus-4-7-xhigh → claude-opus-4-7)
  const { base: withoutEffort } = extractEffortFromModelName(base)
  base = withoutEffort

  // Strip date suffixes (e.g. claude-sonnet-4-20250514 → claude-sonnet-4)
  if (/^claude-sonnet-4-\d{8}/.test(base)) {
    base = "claude-sonnet-4"
  } else if (/^claude-opus-4-\d{8}/.test(base)) {
    base = "claude-opus-4"
  }

  const mapped = MODEL_ID_MAP[base] ?? base.replace(ANTHROPIC_VERSION, "$1.$2")

  const use1M = is1M || has1MBracket || has1MDash

  // Only append -1m if the 1M variant actually exists in the model catalog
  if (use1M) {
    const candidate = `${mapped}-1m`
    const exists = state.models?.data.some((m) => m.id === candidate)
    if (exists) return candidate
  }

  return mapped
}

/**
 * Convert a Copilot-style model ID back to Anthropic-style.
 * Converts dots to dashes and maps -1m back to [1m].
 * Strips -internal suffix (transient preview artifact).
 * Effort is handled via output_config in the request body, not in the model ID.
 */
export function copilotToAnthropicModelId(copilotModel: string): string {
  let base = copilotModel

  // Strip -internal (transient preview suffix)
  if (base.endsWith("-internal")) base = base.slice(0, -9)

  // Strip -1m
  const is1M = base.endsWith("-1m")
  if (is1M) base = base.slice(0, -3)

  const mapped =
    REVERSE_MODEL_ID_MAP[base] ?? base.replace(COPILOT_VERSION, "$1-$2")
  return is1M ? `${mapped}[1m]` : mapped
}

import { describe, expect, it, beforeEach } from "bun:test"

import {
  anthropicToCopilotModelId,
  copilotToAnthropicModelId,
  extractEffortFromModelName,
} from "./model-mapping"
import { state } from "./state"

// Helper to set up model catalog
function setCatalog(ids: Array<string>) {
  state.models = {
    object: "list",
    data: ids.map((id) => ({
      id,
      object: "model",
      created: 0,
      owned_by: "anthropic",
    })),
  } as unknown as typeof state.models
}

describe("anthropicToCopilotModelId", () => {
  beforeEach(() => {
    setCatalog(["claude-opus-4.6", "claude-opus-4.6-1m"])
  })

  it("maps dash format to dot format", () => {
    expect(anthropicToCopilotModelId("claude-opus-4-6", false)).toBe(
      "claude-opus-4.6",
    )
    expect(anthropicToCopilotModelId("claude-sonnet-4-6", false)).toBe(
      "claude-sonnet-4.6",
    )
    expect(anthropicToCopilotModelId("claude-opus-4-5", false)).toBe(
      "claude-opus-4.5",
    )
    expect(anthropicToCopilotModelId("claude-opus-4-7", false)).toBe(
      "claude-opus-4.7",
    )
  })

  it("handles [1m] suffix when model exists in catalog", () => {
    expect(anthropicToCopilotModelId("claude-opus-4-6[1m]", false)).toBe(
      "claude-opus-4.6-1m",
    )
  })

  it("strips [1m] suffix when model not in catalog", () => {
    expect(anthropicToCopilotModelId("claude-sonnet-4-6[1m]", false)).toBe(
      "claude-sonnet-4.6",
    )
  })

  it("passes through unknown models unchanged", () => {
    expect(anthropicToCopilotModelId("gpt-4o", false)).toBe("gpt-4o")
  })

  // Versions are derived, not enumerated: a model released after this file was
  // last edited must still map without a code change.
  it("maps versions with no explicit map entry", () => {
    expect(anthropicToCopilotModelId("claude-opus-4-8", false)).toBe(
      "claude-opus-4.8",
    )
    expect(anthropicToCopilotModelId("claude-opus-4-9", false)).toBe(
      "claude-opus-4.9",
    )
    expect(anthropicToCopilotModelId("claude-haiku-5-2", false)).toBe(
      "claude-haiku-5.2",
    )
  })

  it("leaves single-segment versions alone", () => {
    expect(anthropicToCopilotModelId("claude-sonnet-5", false)).toBe(
      "claude-sonnet-5",
    )
    expect(anthropicToCopilotModelId("claude-opus-5", false)).toBe(
      "claude-opus-5",
    )
  })

  it("never reads a date suffix as a minor version", () => {
    expect(anthropicToCopilotModelId("claude-sonnet-4-20250514", false)).toBe(
      "claude-sonnet-4",
    )
    expect(anthropicToCopilotModelId("claude-opus-4-20250514", false)).toBe(
      "claude-opus-4",
    )
  })

  it("combines a derived version with an effort suffix", () => {
    expect(anthropicToCopilotModelId("claude-opus-4-8-xhigh", false)).toBe(
      "claude-opus-4.8",
    )
  })

  it("handles haiku models", () => {
    expect(anthropicToCopilotModelId("claude-haiku-4-5", false)).toBe(
      "claude-haiku-4.5",
    )
  })

  // ── -internal suffix resolution (backward compat) ──

  it("resolves to -1m when variant exists in catalog", () => {
    setCatalog(["claude-opus-4.7", "claude-opus-4.7-1m"])
    expect(anthropicToCopilotModelId("claude-opus-4.7", true)).toBe(
      "claude-opus-4.7-1m",
    )
    expect(anthropicToCopilotModelId("claude-opus-4.7[1m]", false)).toBe(
      "claude-opus-4.7-1m",
    )
  })

  it("falls back to base model when no -1m variant exists (1M is default)", () => {
    setCatalog(["claude-opus-4.7"])
    expect(anthropicToCopilotModelId("claude-opus-4.7", true)).toBe(
      "claude-opus-4.7",
    )
    expect(anthropicToCopilotModelId("claude-opus-4.7[1m]", false)).toBe(
      "claude-opus-4.7",
    )
  })

  it("prefers -1m over -1m-internal when both exist", () => {
    setCatalog([
      "claude-opus-4.8",
      "claude-opus-4.8-1m",
      "claude-opus-4.8-1m-internal",
    ])
    expect(anthropicToCopilotModelId("claude-opus-4.8", true)).toBe(
      "claude-opus-4.8-1m",
    )
  })

  // ── Effort suffixes are stripped from model name (backward compat) ──
  // Effort is sent via output_config.effort in the request body

  it("strips effort suffix from model name for backward compat", () => {
    setCatalog(["claude-opus-4.7"])
    // Legacy configs like "claude-opus-4-7-xhigh" get the suffix stripped
    expect(anthropicToCopilotModelId("claude-opus-4-7-xhigh", false)).toBe(
      "claude-opus-4.7",
    )
    expect(anthropicToCopilotModelId("claude-opus-4-7-high", false)).toBe(
      "claude-opus-4.7",
    )
  })
})

describe("copilotToAnthropicModelId", () => {
  it("maps dot format to dash format", () => {
    expect(copilotToAnthropicModelId("claude-opus-4.6")).toBe("claude-opus-4-6")
    expect(copilotToAnthropicModelId("claude-opus-4.7")).toBe("claude-opus-4-7")
  })

  it("maps versions with no explicit map entry", () => {
    expect(copilotToAnthropicModelId("claude-opus-4.8")).toBe("claude-opus-4-8")
    expect(copilotToAnthropicModelId("claude-opus-4.9")).toBe("claude-opus-4-9")
  })

  it("round-trips a derived version", () => {
    const copilotId = anthropicToCopilotModelId("claude-opus-4-8", false)
    expect(copilotId).toBe("claude-opus-4.8")
    expect(copilotToAnthropicModelId(copilotId)).toBe("claude-opus-4-8")
  })

  it("leaves single-segment versions alone", () => {
    expect(copilotToAnthropicModelId("claude-sonnet-5")).toBe("claude-sonnet-5")
    expect(copilotToAnthropicModelId("claude-opus-5")).toBe("claude-opus-5")
  })

  it("handles -1m suffix → [1m]", () => {
    expect(copilotToAnthropicModelId("claude-opus-4.6-1m")).toBe(
      "claude-opus-4-6[1m]",
    )
  })

  it("passes through unknown models unchanged", () => {
    expect(copilotToAnthropicModelId("gpt-4o")).toBe("gpt-4o")
  })

  // ── -internal suffix stripping ──

  it("strips -internal and maps -1m to [1m]", () => {
    expect(copilotToAnthropicModelId("claude-opus-4.7-1m-internal")).toBe(
      "claude-opus-4-7[1m]",
    )
  })

  it("strips -internal from non-1m models", () => {
    expect(copilotToAnthropicModelId("claude-opus-4.7-internal")).toBe(
      "claude-opus-4-7",
    )
  })

  // ── Effort suffix handling removed ──
  // These model IDs no longer exist. The upstream always returns base model
  // in response.model anyway (verified in upstream-model-id-report.md).
  // If they somehow appear, they pass through without special handling.

  it("passes through -high suffix unchanged (variant models no longer exist)", () => {
    expect(copilotToAnthropicModelId("claude-opus-4.7-high")).toBe(
      "claude-opus-4.7-high",
    )
  })

  it("passes through -xhigh suffix unchanged (variant models no longer exist)", () => {
    expect(copilotToAnthropicModelId("claude-opus-4.7-xhigh")).toBe(
      "claude-opus-4.7-xhigh",
    )
  })

  // ── Combined suffix scenarios ──

  it("handles -1m + -internal correctly (strip order matters)", () => {
    // This was the bug: endsWith("-1m") failed because it ended with "-1m-internal"
    // Must strip -internal FIRST, then check -1m
    const result = copilotToAnthropicModelId("claude-opus-4.7-1m-internal")
    expect(result).toBe("claude-opus-4-7[1m]")
    // Verify it doesn't produce "claude-opus-4-7-1m" (is1M=false bug)
    expect(result).not.toBe("claude-opus-4-7-1m")
    expect(result).not.toContain("-1m-")
  })

  // ── Full effort routing table ──
  // These test the reverse mapping that clients see in response.model

  it("response model table: base model", () => {
    expect(copilotToAnthropicModelId("claude-opus-4.7")).toBe("claude-opus-4-7")
  })

  it("response model table: effort variants pass through (upstream strips them anyway)", () => {
    // The upstream API returns base model in response.model regardless.
    // These IDs should never appear in practice, but if they do, they pass through.
    expect(copilotToAnthropicModelId("claude-opus-4.7-high")).toBe(
      "claude-opus-4.7-high",
    )
    expect(copilotToAnthropicModelId("claude-opus-4.7-xhigh")).toBe(
      "claude-opus-4.7-xhigh",
    )
  })

  it("response model table: 1m-internal variant", () => {
    expect(copilotToAnthropicModelId("claude-opus-4.7-1m-internal")).toBe(
      "claude-opus-4-7[1m]",
    )
  })

  it("response model table: 4.6 base", () => {
    expect(copilotToAnthropicModelId("claude-opus-4.6")).toBe("claude-opus-4-6")
  })

  it("response model table: 4.6-1m", () => {
    expect(copilotToAnthropicModelId("claude-opus-4.6-1m")).toBe(
      "claude-opus-4-6[1m]",
    )
  })

  // ── Non-Claude models should pass through ──

  it("GPT models pass through unchanged", () => {
    expect(copilotToAnthropicModelId("gpt-5.5")).toBe("gpt-5.5")
    expect(copilotToAnthropicModelId("gpt-5.5-2026-04-23")).toBe(
      "gpt-5.5-2026-04-23",
    )
  })

  it("Gemini models pass through unchanged", () => {
    expect(copilotToAnthropicModelId("gemini-2.5-pro")).toBe("gemini-2.5-pro")
  })
})

// ── -1m dash suffix stripping (backward compat) ──

describe("anthropicToCopilotModelId -1m dash suffix", () => {
  beforeEach(() => {
    setCatalog(["claude-opus-4.6", "claude-opus-4.7"])
  })

  it("strips -1m suffix and resolves to base model (no -1m variant in catalog)", () => {
    expect(anthropicToCopilotModelId("claude-opus-4.6-1m", false)).toBe(
      "claude-opus-4.6",
    )
  })

  it("strips -1m suffix from dash-format model names", () => {
    expect(anthropicToCopilotModelId("claude-opus-4-7-1m", false)).toBe(
      "claude-opus-4.7",
    )
  })

  it("resolves to -1m variant when it exists in catalog", () => {
    setCatalog(["claude-opus-4.6", "claude-opus-4.6-1m"])
    expect(anthropicToCopilotModelId("claude-opus-4.6-1m", false)).toBe(
      "claude-opus-4.6-1m",
    )
  })

  it("treats -1m suffix the same as [1m] suffix", () => {
    setCatalog(["claude-opus-4.6"])
    const dash = anthropicToCopilotModelId("claude-opus-4-6-1m", false)
    const bracket = anthropicToCopilotModelId("claude-opus-4-6[1m]", false)
    expect(dash).toBe(bracket)
  })
})

// ── extractEffortFromModelName ──

describe("extractEffortFromModelName", () => {
  it("extracts -xhigh suffix", () => {
    const result = extractEffortFromModelName("claude-opus-4-7-xhigh")
    expect(result).toEqual({ base: "claude-opus-4-7", effort: "xhigh" })
  })

  it("extracts -high suffix", () => {
    const result = extractEffortFromModelName("claude-opus-4-7-high")
    expect(result).toEqual({ base: "claude-opus-4-7", effort: "high" })
  })

  it("extracts -max suffix", () => {
    const result = extractEffortFromModelName("claude-opus-4-6-max")
    expect(result).toEqual({ base: "claude-opus-4-6", effort: "max" })
  })

  it("extracts -low suffix", () => {
    const result = extractEffortFromModelName("claude-opus-4-6-low")
    expect(result).toEqual({ base: "claude-opus-4-6", effort: "low" })
  })

  it("returns undefined effort for model names without effort suffix", () => {
    const result = extractEffortFromModelName("claude-opus-4.7")
    expect(result).toEqual({ base: "claude-opus-4.7", effort: undefined })
  })

  it("does not confuse -1m with an effort suffix", () => {
    const result = extractEffortFromModelName("claude-opus-4.6-1m")
    expect(result).toEqual({ base: "claude-opus-4.6-1m", effort: undefined })
  })
})

import { createHash } from "node:crypto"
import fs from "node:fs/promises"
import path from "node:path"
import { parse } from "yaml"

import type { ModelsResponse } from "~/services/copilot/get-models"

import { PATHS } from "./paths"

export const COPILOT_PRICING_SOURCE =
  "https://raw.githubusercontent.com/github/docs/main/data/tables/copilot/models-and-pricing.yml"

/**
 * Explicit overrides, for pricing rows whose display name does not reduce to
 * the catalog model ID. The derived rule below covers every ordinary name, so
 * this map only needs an entry when a model breaks the pattern.
 */
const MODEL_ALIASES: Record<string, string> = {
  "Gemini 3 Flash": "gemini-3-flash-preview",
  "Gemini 3.1 Pro": "gemini-3.1-pro-preview",
  "MAI-Code-1-Flash": "mai-code-1-flash-picker",
}

/**
 * Reduce a pricing-table display name to a catalog model ID.
 *
 * The pricing table is documentation, so names carry markdown footnote markers
 * that come and go with promotions — `Claude Sonnet 5[^sonnet-5-promo]` lost
 * its marker and `Gemini 3.6 Flash` gained one, and each change silently broke
 * an exact-string alias. Deriving the ID keeps pricing attached across those
 * edits and across newly released models.
 */
export function pricingNameToModelId(displayName: string): string {
  const withoutFootnotes = displayName.replaceAll(/\[\^[^\]]*\]/g, "")
  return withoutFootnotes.trim().toLowerCase().replaceAll(/\s+/g, "-")
}

/** Characters a Copilot model ID is made of. */
const MODEL_ID_SHAPE = /^[a-z0-9.-]+$/

interface RawPricingRow {
  model?: string
  input?: string | number
  cached_input?: string | number
  cache_write?: string | number
  output?: string | number
  threshold?: string
  tier?: string
  category?: string
}

export interface PricingTier {
  name: "default" | "long-context"
  input_threshold?: { operator: "lte" | "gt"; tokens: number }
  usd_per_1m: {
    input: number | null
    cache_read: number | null
    cache_write: number | null
    output: number | null
  }
  credits_per_1m: {
    input: number | null
    cache_read: number | null
    cache_write: number | null
    output: number | null
  }
}

export interface CopilotModelPricing {
  model: string | null
  display_name: string
  category?: string
  tiers: Array<PricingTier>
}

export interface CopilotPricingCache {
  object: "pricing.list"
  provider: "github-copilot"
  currency: "USD"
  unit: "per_1m_tokens"
  credit: { usd_per_credit: 0.01 }
  source: {
    url: string
    version: string
    upstream_etag?: string
    public_etag?: string
    fetched_at: string
    validated_at: string
    stale: boolean
    error?: string
    last_attempt_at?: string
  }
  data: Array<CopilotModelPricing>
  unmatched_models: Array<string>
}

function parsePrice(value: string | number | undefined): number | null {
  if (typeof value === "number") return value
  if (!value || value === "Not applicable") return null
  const parsed = Number(value.replaceAll(/[$,]/g, ""))
  return Number.isFinite(parsed) ? parsed : null
}

function parseThreshold(
  value: string | undefined,
): PricingTier["input_threshold"] {
  if (!value) return undefined
  const match = value.match(/(≤|>)\s*([\d.]+)K/)
  if (!match) return undefined
  return {
    operator: match[1] === "≤" ? "lte" : "gt",
    tokens: Math.round(Number(match[2]) * 1000),
  }
}

function toCredits(value: number | null): number | null {
  return value === null ? null : value / 0.01
}

export function parseCopilotPricingYaml(
  yaml: string,
  metadata: { etag?: string; fetchedAt?: string } = {},
): CopilotPricingCache {
  const rows = parse(yaml) as Array<RawPricingRow>
  if (rows.length === 0)
    throw new Error("Pricing source contains no model rows")

  const grouped = new Map<string, Array<RawPricingRow>>()
  for (const row of rows) {
    if (!row.model || row.input === undefined || row.output === undefined) {
      throw new Error("Pricing row is missing required fields")
    }
    const modelName = row.model
    const validRow = row as RawPricingRow & {
      model: string
      input: string | number
      output: string | number
    }
    grouped.set(modelName, [...(grouped.get(modelName) ?? []), validRow])
  }

  const unmatched: Array<string> = []
  const data = [...grouped.entries()].map(([displayName, modelRows]) => {
    const derived =
      MODEL_ALIASES[displayName] ?? pricingNameToModelId(displayName)
    // A derived name that still carries prose (e.g. "(fast mode) (preview)")
    // is a documentation row rather than a model, so it stays unattached.
    const model = MODEL_ID_SHAPE.test(derived) ? derived : null
    if (!model) unmatched.push(displayName)
    const tiers = modelRows.map((row, index): PricingTier => {
      const input = parsePrice(row.input)
      const cacheRead = parsePrice(row.cached_input)
      const cacheWrite = parsePrice(row.cache_write)
      const output = parsePrice(row.output)
      return {
        name:
          row.tier?.toLowerCase().includes("long") || index > 0 ?
            "long-context"
          : "default",
        input_threshold: parseThreshold(row.threshold),
        usd_per_1m: {
          input,
          cache_read: cacheRead,
          cache_write: cacheWrite,
          output,
        },
        credits_per_1m: {
          input: toCredits(input),
          cache_read: toCredits(cacheRead),
          cache_write: toCredits(cacheWrite),
          output: toCredits(output),
        },
      }
    })
    return {
      model,
      display_name: displayName,
      category: modelRows[0].category?.toLowerCase(),
      tiers,
    }
  })

  const now = metadata.fetchedAt ?? new Date().toISOString()
  return {
    object: "pricing.list",
    provider: "github-copilot",
    currency: "USD",
    unit: "per_1m_tokens",
    credit: { usd_per_credit: 0.01 },
    source: {
      url: COPILOT_PRICING_SOURCE,
      version: `sha256:${createHash("sha256").update(yaml).digest("hex")}`,
      upstream_etag: metadata.etag,
      fetched_at: now,
      validated_at: now,
      stale: false,
    },
    data,
    unmatched_models: unmatched,
  }
}

export async function readCopilotPricing(
  cachePath = PATHS.COPILOT_PRICING_PATH,
): Promise<CopilotPricingCache | undefined> {
  try {
    return JSON.parse(
      (await fs.readFile(cachePath)).toString("utf8"),
    ) as CopilotPricingCache
  } catch {
    return undefined
  }
}

export async function writeCopilotPricing(
  cache: CopilotPricingCache,
  cachePath = PATHS.COPILOT_PRICING_PATH,
): Promise<void> {
  await fs.mkdir(path.dirname(cachePath), { recursive: true })
  const temporaryPath = `${cachePath}.tmp-${process.pid}`
  await fs.writeFile(temporaryPath, `${JSON.stringify(cache, null, 2)}\n`, {
    mode: 0o600,
  })
  await fs.rename(temporaryPath, cachePath)
}

export async function updateCopilotPricing(
  fetcher: typeof fetch = fetch,
  cachePath = PATHS.COPILOT_PRICING_PATH,
): Promise<{
  status: "updated" | "not-modified" | "stale"
  cache?: CopilotPricingCache
}> {
  const existing = await readCopilotPricing(cachePath)
  try {
    const response = await fetcher(COPILOT_PRICING_SOURCE, {
      headers:
        existing?.source.upstream_etag ?
          { "if-none-match": existing.source.upstream_etag }
        : undefined,
      signal: AbortSignal.timeout(30_000),
    })
    if (response.status === 304 && existing) {
      const recovered = structuredClone(existing)
      recovered.source.validated_at = new Date().toISOString()
      recovered.source.stale = false
      delete recovered.source.error
      await writeCopilotPricing(recovered, cachePath)
      return { status: "not-modified", cache: recovered }
    }
    if (!response.ok)
      throw new Error(`Pricing fetch failed with HTTP ${response.status}`)
    const cache = parseCopilotPricingYaml(await response.text(), {
      etag: response.headers.get("etag") ?? undefined,
    })
    await writeCopilotPricing(cache, cachePath)
    return { status: "updated", cache }
  } catch (error) {
    if (!existing) throw error
    const stale = structuredClone(existing)
    stale.source.last_attempt_at = new Date().toISOString()
    stale.source.stale = true
    stale.source.error = error instanceof Error ? error.message : String(error)
    await writeCopilotPricing(stale, cachePath)
    return { status: "stale", cache: stale }
  }
}

export interface PublishedPricing extends CopilotPricingCache {
  diagnostics: {
    mapped_but_inaccessible: Array<string>
    accessible_without_pricing: Array<string>
  }
}

export function publishCopilotPricing(
  cache: CopilotPricingCache,
  models: ModelsResponse | undefined,
): PublishedPricing {
  const accessible = new Set(models?.data.map((model) => model.id) ?? [])
  const publishedData = cache.data.filter(
    (item): item is CopilotModelPricing & { model: string } =>
      Boolean(item.model && accessible.has(item.model)),
  )
  const priced = new Set(publishedData.map((item) => item.model))
  const mappedButInaccessible = cache.data.flatMap((item) =>
    item.model && !accessible.has(item.model) ? [item.model] : [],
  )
  const accessibleWithoutPricing = [...accessible].filter(
    (model) => !priced.has(model),
  )
  const publicEtag = `"${createHash("sha256")
    .update(
      JSON.stringify({
        source_version: cache.source.version,
        stale: cache.source.stale,
        error: cache.source.error,
        data: publishedData,
        unmatched_models: cache.unmatched_models,
        mapped_but_inaccessible: mappedButInaccessible,
        accessible_without_pricing: accessibleWithoutPricing,
      }),
    )
    .digest("hex")}"`
  return {
    ...cache,
    source: { ...cache.source, public_etag: publicEtag },
    data: publishedData,
    diagnostics: {
      mapped_but_inaccessible: mappedButInaccessible,
      accessible_without_pricing: accessibleWithoutPricing,
    },
  }
}

export function pricingEtagMatches(
  ifNoneMatch: string | undefined,
  etag: string,
): boolean {
  return (
    ifNoneMatch
      ?.split(",")
      .map((value) => value.trim().replace(/^W\//, ""))
      .includes(etag) ?? false
  )
}

export function pricingForModel(
  cache: CopilotPricingCache | undefined,
  modelId: string,
): CopilotModelPricing | undefined {
  return cache?.data.find((item) => item.model === modelId)
}

import { describe, expect, it } from "bun:test"

import {
  parseCopilotPricingYaml,
  pricingNameToModelId,
  pricingEtagMatches,
  pricingForModel,
  publishCopilotPricing,
} from "~/lib/copilot-pricing"

const FIXTURE = `
- model: GPT-5.6 Sol
  provider: openai
  category: Powerful
  threshold: '≤ 272K'
  tier: Default
  input: $5.00
  cached_input: $0.50
  output: $30.00
- model: GPT-5.6 Sol
  provider: openai
  category: Powerful
  threshold: '> 272K'
  tier: 'Long context'
  input: $10.00
  cached_input: $1.00
  output: $45.00
- model: Claude Haiku 4.5
  provider: anthropic
  category: Versatile
  input: $1.00
  cached_input: $0.10
  output: $5.00
  cache_write: $1.25
`

describe("Copilot pricing parser", () => {
  it("parses default and long-context GPT pricing", () => {
    const pricing = parseCopilotPricingYaml(FIXTURE, {
      etag: '"fixture"',
      fetchedAt: "2026-01-01T00:00:00.000Z",
    })
    const sol = pricingForModel(pricing, "gpt-5.6-sol")

    expect(sol?.category).toBe("powerful")
    expect(sol?.tiers).toHaveLength(2)
    expect(sol?.tiers[0]).toMatchObject({
      name: "default",
      input_threshold: { operator: "lte", tokens: 272_000 },
      credits_per_1m: {
        input: 500,
        cache_read: 50,
        cache_write: null,
        output: 3000,
      },
    })
    expect(sol?.tiers[1]).toMatchObject({
      name: "long-context",
      input_threshold: { operator: "gt", tokens: 272_000 },
      credits_per_1m: { input: 1000, output: 4500 },
    })
    expect(pricing.source.upstream_etag).toBe('"fixture"')
    expect(pricing.source.version).toStartWith("sha256:")
  })

  it("parses Anthropic cache-write pricing", () => {
    const pricing = parseCopilotPricingYaml(FIXTURE)
    expect(
      pricingForModel(pricing, "claude-haiku-4.5")?.tiers[0],
    ).toMatchObject({
      credits_per_1m: {
        input: 100,
        cache_read: 10,
        cache_write: 125,
        output: 500,
      },
    })
  })

  // Reversal of an earlier "report unmatched rather than guess" rule. That
  // rule was conservative about billing data, but it was measured dropping
  // pricing for ten live models, two of which regressed only because a
  // promotion footnote appeared or disappeared. Deriving is inert when wrong,
  // since lookups are keyed by live catalog IDs and an entry for a model that
  // does not exist is never read; not deriving is silently wrong for models
  // that do exist.
  it("derives an ID for a well-formed unknown name", () => {
    const pricing = parseCopilotPricingYaml(
      `${FIXTURE}\n- model: Future Model\n  input: $1\n  output: $2\n`,
    )
    expect(pricing.unmatched_models).toEqual([])
    expect(pricingForModel(pricing, "future-model")).toBeTruthy()
  })

  it("attaches a derived entry to no other model", () => {
    const pricing = parseCopilotPricingYaml(
      `${FIXTURE}\n- model: Future Model\n  input: $1\n  output: $2\n`,
    )
    expect(pricingForModel(pricing, "gpt-5.6-sol")).toBeTruthy()
    expect(pricingForModel(pricing, "nonexistent-model")).toBeFalsy()
  })

  it("rejects structurally empty sources", () => {
    expect(() => parseCopilotPricingYaml("[]")).toThrow(
      "Pricing source contains no model rows",
    )
  })

  it("publishes only models in the accessible catalog without blocking others", () => {
    const pricing = parseCopilotPricingYaml(FIXTURE)
    const published = publishCopilotPricing(pricing, {
      object: "list",
      data: [
        {
          id: "gpt-5.6-sol",
          name: "GPT-5.6 Sol",
          object: "model",
          vendor: "openai",
          version: "1",
          preview: false,
          model_picker_enabled: true,
          capabilities: {
            family: "gpt",
            limits: {},
            object: "model_capabilities",
            supports: {},
            tokenizer: "test",
            type: "chat",
          },
        },
        {
          id: "accessible-without-price",
          name: "Accessible",
          object: "model",
          vendor: "test",
          version: "1",
          preview: false,
          model_picker_enabled: true,
          capabilities: {
            family: "test",
            limits: {},
            object: "model_capabilities",
            supports: {},
            tokenizer: "test",
            type: "chat",
          },
        },
      ],
    })

    expect(published.data.map((item) => item.model)).toEqual(["gpt-5.6-sol"])
    expect(published.diagnostics.accessible_without_pricing).toContain(
      "accessible-without-price",
    )
    expect(published.source.public_etag).toMatch(/^"[a-f0-9]{64}"$/)
  })

  it("keeps the public ETag stable across timestamp-only changes", () => {
    const pricing = parseCopilotPricingYaml(FIXTURE)
    const models = {
      object: "list" as const,
      data: [
        {
          id: "gpt-5.6-sol",
          name: "GPT-5.6 Sol",
          object: "model",
          vendor: "openai",
          version: "1",
          preview: false,
          model_picker_enabled: true,
          capabilities: {
            family: "gpt",
            limits: {},
            object: "model_capabilities",
            supports: {},
            tokenizer: "test",
            type: "chat",
          },
        },
      ],
    }
    const first = publishCopilotPricing(pricing, models)
    pricing.source.validated_at = "2099-01-01T00:00:00.000Z"
    pricing.source.last_attempt_at = "2099-01-01T00:00:00.000Z"
    const second = publishCopilotPricing(pricing, models)
    expect(second.source.public_etag).toBe(first.source.public_etag)
  })

  it("matches strong and weak conditional ETags", () => {
    expect(pricingEtagMatches('W/"abc", "other"', '"abc"')).toBe(true)
    expect(pricingEtagMatches('"other"', '"abc"')).toBe(false)
  })
})

describe("pricing display name derivation", () => {
  it("lowercases and dashes ordinary names", () => {
    expect(pricingNameToModelId("GPT-6 Astra")).toBe("gpt-6-astra")
    expect(pricingNameToModelId("Claude Opus 5")).toBe("claude-opus-5")
    expect(pricingNameToModelId("Grok 4.6")).toBe("grok-4.6")
    expect(pricingNameToModelId("GPT-5.4 mini")).toBe("gpt-5.4-mini")
    expect(pricingNameToModelId("MAI-Code-1.1-Flash")).toBe(
      "mai-code-1.1-flash",
    )
  })

  // Promotions add and remove these markers, which silently broke exact-string
  // aliases for Gemini 3.6 Flash and Claude Sonnet 5.
  it("strips markdown footnote markers", () => {
    expect(pricingNameToModelId("Gemini 3.6 Flash[^gemini-flash-promo]")).toBe(
      "gemini-3.6-flash",
    )
    expect(pricingNameToModelId("Claude Sonnet 5[^sonnet-5-promo]")).toBe(
      "claude-sonnet-5",
    )
  })

  it("is unaffected by a marker appearing or disappearing", () => {
    expect(pricingNameToModelId("Claude Sonnet 5")).toBe(
      pricingNameToModelId("Claude Sonnet 5[^sonnet-5-promo]"),
    )
  })

  it("attaches pricing for a model with no explicit alias", () => {
    const parsed = parseCopilotPricingYaml(`
- model: GPT-6 Astra
  provider: openai
  input: $1.00
  cached_input: $0.10
  output: $2.00
`)
    expect(pricingForModel(parsed, "gpt-6-astra")).toBeTruthy()
    expect(parsed.unmatched_models).toEqual([])
  })

  it("leaves a prose documentation row unattached", () => {
    const parsed = parseCopilotPricingYaml(`
- model: Claude Opus 4.8 (fast mode) (preview)
  provider: anthropic
  input: $1.00
  output: $2.00
`)
    expect(parsed.unmatched_models).toEqual([
      "Claude Opus 4.8 (fast mode) (preview)",
    ])
  })
})
